-- SQL Quest practice dataset "movies": FlickNest
-- Generated by scripts/gen-datasets.mjs (deterministic) - edit the generator, not this file.

CREATE TABLE movies (
    movie_id        integer PRIMARY KEY,
    title           text NOT NULL,
    release_year    integer NOT NULL,
    duration_min    integer NOT NULL,
    age_rating      text NOT NULL,
    language        text NOT NULL,
    budget_musd     numeric(6,1),
    box_office_musd numeric(7,1)
);

CREATE TABLE genres (
    genre_id integer PRIMARY KEY,
    name     text NOT NULL UNIQUE
);

CREATE TABLE movie_genres (
    movie_id integer NOT NULL REFERENCES movies (movie_id),
    genre_id integer NOT NULL REFERENCES genres (genre_id),
    PRIMARY KEY (movie_id, genre_id)
);

CREATE TABLE people (
    person_id  integer PRIMARY KEY,
    full_name  text NOT NULL,
    birth_year integer,
    country    text NOT NULL
);

CREATE TABLE movie_cast (
    movie_id       integer NOT NULL REFERENCES movies (movie_id),
    person_id      integer NOT NULL REFERENCES people (person_id),
    role           text NOT NULL,
    character_name text,
    billing_order  integer,
    PRIMARY KEY (movie_id, person_id, role)
);

CREATE TABLE users (
    user_id     integer PRIMARY KEY,
    username    text NOT NULL UNIQUE,
    country     text NOT NULL,
    signup_date date NOT NULL,
    plan        text NOT NULL
);

CREATE TABLE ratings (
    user_id  integer NOT NULL REFERENCES users (user_id),
    movie_id integer NOT NULL REFERENCES movies (movie_id),
    stars    numeric(2,1) NOT NULL CHECK (stars BETWEEN 0.5 AND 5.0),
    rated_at timestamp NOT NULL,
    PRIMARY KEY (user_id, movie_id)
);

CREATE TABLE watch_history (
    watch_id        integer PRIMARY KEY,
    user_id         integer NOT NULL REFERENCES users (user_id),
    movie_id        integer NOT NULL REFERENCES movies (movie_id),
    started_at      timestamp NOT NULL,
    minutes_watched integer NOT NULL,
    device          text NOT NULL
);




















ANALYZE;
